-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_PARTY_DIGITAL_IDENTITY
--   anchor      : HUB_PARTY
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Active Sequence Number
--   feeders     : 3 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PARTY_BK__K7)) as HUB_PARTY_HK,
        'POLICYHOLDER_PORTAL' as ACTIVE_SEQUENCE_NUMBER,
        null::varchar as LOGIN_IDENTIFIER,
        POLICYHOLDER_PORTAL as CHANNEL_REGISTERED,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_PARTY_K7__EMIT
    union all
    select
        md5(upper(HUB_PARTY_BK__K1)) as HUB_PARTY_HK,
        'SMART_PHONE' as ACTIVE_SEQUENCE_NUMBER,
        null::varchar as LOGIN_IDENTIFIER,
        null::varchar as CHANNEL_REGISTERED,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_ppd_pv') }}
    where HUB_PARTY_K1__EMIT
    union all
    select
        md5(upper(HUB_PARTY_BK__K2)) as HUB_PARTY_HK,
        'GROUP_HEALTH_PORTAL' as ACTIVE_SEQUENCE_NUMBER,
        USER_CODE as LOGIN_IDENTIFIER,
        null::varchar as CHANNEL_REGISTERED,
        'MAXI_HLTH_UWR_VW_DATA_RELATIONS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_relations_ppd_pv') }}
    where HUB_PARTY_K2__EMIT
)), hashed as (select *,
        case when LOGIN_IDENTIFIER is not null or CHANNEL_REGISTERED is not null
             then md5(upper(coalesce(LOGIN_IDENTIFIER::varchar,'') || '||' || coalesce(CHANNEL_REGISTERED::varchar,'')))
        end as SAT_PARTY_DIGITAL_IDENTITY_HASHDIFF
    from feeders)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_DIGITAL_IDENTITY_HASHDIFF is not null
  and ACTIVE_SEQUENCE_NUMBER is not null
